import{_ as a,o as t,c as s,a6 as n}from"./chunks/framework.CKIbuWFA.js";const f=JSON.parse('{"title":"Configurer les sons et la synthèse vocale","description":"","frontmatter":{"title":"Configurer les sons et la synthèse vocale","docId":"user.plugins.audio","translationKey":"user.plugins.audio","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"b6be887705d13dfe120f3e07dc4006ec0efa1472b6dbe0ccfc1ebfc1e83f3672","translationRevision":"182dd11d2f6abc8d64e79750f1ae4a9a76ab4d073ede596b55c78f995c9d9ea7","order":20},"headers":[],"relativePath":"fr/user/plugins/audio.md","filePath":"fr/user/plugins/audio.md","lastUpdated":1794611623000}'),o={name:"fr/user/plugins/audio.md"};function i(r,e,l,u,c,d){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="set-up-sounds-and-speech" tabindex="-1">Configurer les sons et la synthèse vocale <a class="header-anchor" href="#set-up-sounds-and-speech" aria-label="Permalink to &quot;Configurer les sons et la synthèse vocale {#set-up-sounds-and-speech}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Jouer un son prévisible avant de relier l’audio à une activité LIVE intense. Il faut un périphérique de sortie fonctionnel et un fichier audio existant pris en charge. L’action locale <strong>Play a sound</strong> (<code>audio.play</code>) est intégrée ; les fournisseurs vocaux, comme une intégration SonicBoom installée, nécessitent leur propre configuration de plugin/service.</p><h2 id="test-a-local-sound" tabindex="-1">Tester un son local <a class="header-anchor" href="#test-a-local-sound" aria-label="Permalink to &quot;Tester un son local {#test-a-local-sound}&quot;">​</a></h2><ol><li>Dans <strong>Automations → Actions</strong>, créez <strong>Play a sound</strong> (<code>audio.play</code>). Sélectionnez un fichier existant avec le sélecteur de médias.</li><li>Réglez le volume à <code>0.2</code> pour une première vérification. La plage prise en charge va de <code>0</code> à <code>1</code> ; zéro est silencieux.</li><li>Choisissez la politique de chevauchement : <code>allow</code> autorise les lectures simultanées, <code>restart</code> redémarre le son et <code>drop</code> ignore une nouvelle instance pendant sa lecture.</li><li>Enregistrez l’action et lisez sa configuration avant de sélectionner <strong>Test</strong>. Ce test peut émettre un son audible.</li><li>Écoutez avec le périphérique souhaité. Après une lecture locale réussie, reliez l’action à un événement avec un <a href="./../automations/recipes.html">filtre et un délai</a> prudents.</li></ol><p>L’action conserve une référence de média fondée sur un chemin. TikTools ne copie pas le fichier audio dans sa base de données. Gardez le fichier à cet emplacement et incluez-le séparément lors du déplacement ou de la sauvegarde de votre configuration.</p><h2 id="configure-optional-speech" tabindex="-1">Configurer la synthèse vocale facultative <a class="header-anchor" href="#configure-optional-speech" aria-label="Permalink to &quot;Configurer la synthèse vocale facultative {#configure-optional-speech}&quot;">​</a></h2><p>Installez le plugin vocal de confiance via <a href="./">Plugins</a>. Dans ses commandes de connexion/paramètres, vérifiez l’adresse du service, l’authentification et les choix de fournisseur, langue et voix/profil. Chargez un catalogue de voix avant de tester une courte phrase non sensible. Une voix manquante doit être examinée comme un problème de catalogue, de propriété ou de fournisseur, sans la remplacer par un identifiant inventé.</p><p>Pour SonicBoom, la synthèse, l’admission en lecture et la fin audible sont des résultats différents. Une réponse mise en file ou démarrée ne prouve pas qu’une personne a entendu la phrase. La voix clonée peut être plus lente que l’arrivée des messages : examinez les diagnostics de file/saturation et gardez l’admission des événements bornée.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Résultat attendu, état et récupération <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Résultat attendu, état et récupération {#expected-result-status-and-recovery}&quot;">​</a></h2><p>La lecture audio locale est disponible lorsque l’hôte annonce la prise en charge audio. La synthèse vocale reste dépendante du plugin installé et d’un service accessible ; la validation du fournisseur, du périphérique ou de la plateforme n’est pas garantie ici. En cas de silence, vérifiez l’existence du fichier, le volume, la sortie, l’état de pause et l’erreur d’exécution. Si la synthèse échoue, vérifiez le service et le catalogue de voix avant de réessayer. Évitez les tests d’effets répétés pendant une diffusion et utilisez les <a href="./../preferences/troubleshooting.html">diagnostics</a> sans partager de jetons ou de texte privé prononcé.</p>',11)])])}const h=a(o,[["render",i]]);export{f as __pageData,h as default};
